<template>
 <div class="app-container stock-sync">
  <div class="heading"><div><h2>平台库存同步</h2><p>按店铺与 OMS SKU 管理库存，一份可售数量按比例分配到多个平台链接。</p></div><el-button v-hasPermi="['channel:stockSync:edit']" type="primary" icon="el-icon-plus" @click="create">新建同步组</el-button></div>
  <el-form inline size="small" @submit.native.prevent="search"><el-form-item label="店铺"><el-select v-model="query.channelId" clearable filterable><el-option v-for="s in shops" :key="s.channel_id" :value="s.channel_id" :label="s.channel_name" /></el-select></el-form-item><el-form-item label="OMS SKU"><el-input v-model.trim="query.skuSn" clearable @keyup.enter.native="search" /></el-form-item><el-button type="primary" @click="search">查询</el-button><el-button @click="load">刷新</el-button></el-form>
  <el-alert v-if="error" :title="error" type="error" :closable="false" />
  <el-table v-loading="loading" :data="rows" row-key="id"><el-table-column prop="channel_name" label="店铺" min-width="170" /><el-table-column prop="sku_sn" label="OMS SKU" min-width="190" /><el-table-column prop="link_count" label="平台链接" width="100" /><el-table-column label="上次测算可售 / 目标" min-width="160"><template slot-scope="s">{{ s.row.available_quantity == null ? '—' : s.row.available_quantity }} / {{ s.row.target_quantity == null ? '—' : s.row.target_quantity }}<div v-if="s.row.retained_quantity" class="muted">停用链接占用 {{ s.row.retained_quantity }}</div></template></el-table-column><el-table-column label="自动同步" width="120"><template slot-scope="s"><el-tag size="mini" :type="s.row.enabled ? 'success' : 'info'">{{ s.row.enabled ? '已开启' : '已关闭' }}</el-tag><div v-if="!s.row.sync_enabled" class="warn">店铺总开关关闭</div></template></el-table-column><el-table-column label="最近结果" min-width="230"><template slot-scope="s"><el-tag size="mini" :type="tone(s.row.state)">{{ state(s.row.state) }}</el-tag><div class="muted">{{ s.row.last_run_at || '尚未执行' }}</div><div v-if="s.row.last_error" class="warn">{{ s.row.last_error }}</div></template></el-table-column><el-table-column label="操作" width="190" fixed="right"><template slot-scope="s"><el-button type="text" @click="open(s.row.id)">详情 / 配置</el-button><el-button v-hasPermi="['channel:stockSync:execute']" type="text" :disabled="busyState(s.row.state)" @click="enqueue(s.row)">提交同步</el-button></template></el-table-column></el-table>
  <pagination v-show="total > 0" :total="total" :page.sync="query.pageNum" :limit.sync="query.pageSize" @pagination="load" />
  <el-drawer :title="form.id ? '库存同步组 · ' + form.sku_sn : '新建库存同步组'" :visible.sync="visible" size="min(1320px, 96vw)" append-to-body :wrapper-closable="false" @close="close">
   <div v-loading="detailLoading" class="workspace"><el-alert v-if="detailError" :title="detailError" type="error" :closable="false" />
    <template v-if="!detailError"><el-alert v-if="form.simulation" title="模拟平台：同步结果只写入本地模拟库存，不会修改真实店铺。" type="warning" :closable="false" show-icon /><el-alert title="同步只修改平台可售数量，不新增或扣减 OMS 实物库存。关闭同步不会自动清空平台库存。" type="info" :closable="false" show-icon />
     <el-form label-position="top" size="small" class="settings"><el-form-item label="店铺"><el-select v-model="form.channel_id" :disabled="!!form.id" filterable @change="loadBindings"><el-option v-for="s in shops" :key="s.channel_id" :value="s.channel_id" :label="s.channel_name" /></el-select></el-form-item><el-form-item label="OMS SKU"><el-input v-model.trim="form.sku_sn" :disabled="!!form.id" maxlength="128" @change="loadBindings" /></el-form-item><el-form-item label="安全库存（按组扣一次）"><el-input-number v-model="form.safety_stock" :min="0" :max="2147483647" :precision="0" /></el-form-item><el-form-item label="总投放上限（空为不限）"><el-input-number v-model="form.quantity_cap" :min="0" :max="2147483647" :precision="0" /></el-form-item><el-form-item label="自动同步"><el-switch v-model="form.enabled" :active-value="1" :inactive-value="0" /></el-form-item></el-form>
     <el-alert v-if="selectedShop && !selectedShop.sync_enabled" title="店铺库存同步总开关未开启。可以保存和预览，执行前请到渠道店铺管理开启。" type="warning" :closable="false" />
     <div class="section"><h3>销售链接</h3><el-button v-hasPermi="['channel:stockSync:edit']" size="small" :disabled="form.links.length >= 20 || busy" @click="addLink">添加链接</el-button></div><p class="muted">按权重比例分配，例如 60 : 30 : 10。链接上限截留的数量不自动转投其他链接。请从平台商品中已确认绑定的销售链接选择，平台 ID 和规格随绑定带入。</p>
     <el-table :data="form.links" size="small"><el-table-column label="链接名称" min-width="145"><template slot-scope="s"><el-input v-model.trim="s.row.name" maxlength="100" /></template></el-table-column><el-table-column label="已绑定平台商品 / 规格" min-width="330"><template slot-scope="s"><template v-if="s.row.retired_at"><el-tag type="info" size="mini">已清零退出</el-tag><div>{{ s.row.item_id }} / {{ s.row.sku_id }}</div></template><template v-else><el-select v-model="s.row.binding_id" filterable placeholder="选择有效的商品绑定" @change="chooseBinding(s.row)"><el-option v-for="b in bindingOptions.filter(b => editable(s.row) || (b.item_id === s.row.item_id && b.sku_id === s.row.sku_id))" :key="b.binding_id" :value="b.binding_id" :label="b.title + ' · ' + (b.spec_name || '无规格') + ' · ' + b.item_id + '/' + b.sku_id" /></el-select><div class="muted">{{ s.row.item_id || '商品 ID' }} / {{ s.row.sku_id || 'SKU ID' }} · 绑定版本 {{ s.row.binding_revision || '未选择' }}</div></template></template></el-table-column><el-table-column label="权重" width="105"><template slot-scope="s"><el-input-number v-model="s.row.weight" :disabled="!!s.row.retired_at" :min="1" :max="10000" :controls="false" :precision="0" style="width:85px" /></template></el-table-column><el-table-column label="数量上限" width="115"><template slot-scope="s"><el-input-number v-model="s.row.quantity_cap" :min="0" :max="2147483647" :controls="false" :precision="0" style="width:95px" /></template></el-table-column><el-table-column label="参与分配" width="90"><template slot-scope="s"><el-switch v-model="s.row.enabled" :disabled="!!s.row.retired_at" :active-value="1" :inactive-value="0" /></template></el-table-column><el-table-column label="操作" min-width="150"><template slot-scope="s"><el-button v-if="editable(s.row)" type="text" @click="form.links.splice(s.$index, 1)">移除</el-button><template v-else-if="!s.row.retired_at"><el-button v-hasPermi="['channel:stockSync:execute']" type="text" :disabled="busy" @click="linkAction(s.row, 'ZERO_DISABLE')">清零并退出</el-button><el-button v-if="s.row.state === 'UNKNOWN'" v-hasPermi="['channel:stockSync:execute']" type="text" :disabled="busy" @click="linkAction(s.row, 'CONFIRM_CURRENT')">核对当前结果</el-button></template></template></el-table-column></el-table>
     <el-button type="text" @click="loadBindings">刷新可选绑定</el-button><el-button type="text" @click="$router.push({path:'/oms-channel/platformProducts',query:{channelId:form.channel_id}})">前往平台商品拉取 / 绑定</el-button><p class="warn">停用链接不会清零；执行时仍查询其平台库存并扣除占用的投放预算。需要释放额度，请使用“清零并退出”。</p>
     <div class="actions"><el-button v-hasPermi="['channel:stockSync:edit']" type="primary" :loading="busy" :disabled="busyState(form.state)" @click="save">保存配置</el-button><el-button :disabled="!form.id || busy" @click="preview">预览分配</el-button><el-button v-hasPermi="['channel:stockSync:execute']" :disabled="!form.id || busy || busyState(form.state)" @click="enqueue(form)">提交同步</el-button><el-button v-if="form.id" @click="open(form.id)">刷新详情</el-button><platform-log-link v-if="form.id" :channel-id="form.channel_id" category="STOCK" /></div>
     <template v-if="projection"><h3>分配预览 <el-tag size="mini" type="info">未提交平台</el-tag></h3><div class="summary"><div>店铺可售<strong>{{ projection.stock.available }}</strong></div><div>商品类型<strong>{{ projection.stock.goods_type }}</strong></div><div>分配目标合计<strong>{{ projection.links.reduce((n, l) => n + l.target, 0) }}</strong></div></div><el-alert v-if="!projection.guard.can_increase" :title="projection.guard.reason" type="warning" :closable="false" /><p class="muted">{{ projection.notice }}</p><el-table :data="projection.links" size="small"><el-table-column prop="name" label="销售链接" /><el-table-column prop="target" label="本地计算目标" /><el-table-column prop="last_submitted" label="最近成功提交" /><el-table-column label="平台观测库存"><template slot-scope="s">{{ s.row.observed_quantity == null ? '尚未查询' : s.row.observed_quantity }}<div class="muted">{{ s.row.observed_at }}</div></template></el-table-column></el-table></template>
     <template v-if="form.id"><h3>链接同步结果</h3><el-table :data="form.links" size="small"><el-table-column prop="name" label="链接" /><el-table-column label="最近成功提交"><template slot-scope="s">{{ s.row.last_submitted == null ? '—' : s.row.last_submitted }}<div class="muted">{{ s.row.submitted_at }}</div></template></el-table-column><el-table-column label="平台观测库存"><template slot-scope="s">{{ s.row.observed_quantity == null ? '—' : s.row.observed_quantity }}<div class="muted">{{ s.row.observed_at }}</div></template></el-table-column><el-table-column label="结果"><template slot-scope="s"><el-tag size="mini" :type="tone(s.row.state)">{{ state(s.row.state) }}</el-tag><div class="warn">{{ s.row.last_error }}</div></template></el-table-column></el-table>
      <h3>最近执行记录</h3><el-table :data="form.runs || []" size="small"><el-table-column prop="create_time" label="执行时间" min-width="170" /><el-table-column label="结果" width="130"><template slot-scope="s">{{ state(s.row.state) }}</template></el-table-column><el-table-column prop="last_error" label="处理说明" min-width="280" /><el-table-column width="100" label="操作"><template slot-scope="s"><el-button type="text" @click="showRun(s.row)">查看明细</el-button></template></el-table-column></el-table>
     </template>
    </template>
   </div>
  </el-drawer>
  <el-dialog title="库存同步执行明细" :visible.sync="runVisible" width="min(1100px, 95vw)" append-to-body><template v-if="run"><el-alert :title="state(run.state) + (run.last_error ? '：' + run.last_error : '')" :type="tone(run.state) === 'success' ? 'success' : 'info'" :closable="false" /><p>请求编号：{{ run.request_id }}</p><platform-log-link :number="run.request_id" number-type="TASK" :channel-id="form.channel_id" category="STOCK" /><template v-if="run.snapshot"><p>投放预算：{{ run.snapshot.budget }} · 停用链接平台库存：{{ run.snapshot.retained_exposure }}</p><el-table :data="run.snapshot.links || []"><el-table-column prop="name" label="链接" /><el-table-column prop="observed_quantity" label="执行前观测" /><el-table-column prop="target" label="计划数量" /><el-table-column prop="submitted_quantity" label="本次提交" /><el-table-column label="结果"><template slot-scope="s">{{ s.row.result === 'BLOCKED' ? '暂停补高' : s.row.result === 'SUCCESS' ? '成功' : '未修改' }}</template></el-table-column></el-table></template></template></el-dialog>
 </div>
</template>
<script>
import { stockGet, stockPost } from '@/api/channel/stockSync'
import { productGet } from '@/api/channel/products'
import PlatformLogLink from '@/views/oms/channel/PlatformLogLink'
const blank = () => ({ channel_id: undefined, sku_sn: '', safety_stock: 0, quantity_cap: undefined, enabled: 0, links: [] })
export default {
 name: 'PlatformStockSync', components: { PlatformLogLink },
 data() { return { query: { channelId: undefined, skuSn: '', pageNum: 1, pageSize: 20 }, shops: [], rows: [], total: 0, loading: false, error: '', visible: false, detailLoading: false, detailError: '', busy: false, form: blank(), bindingOptions: [], bindingSequence: 0, projection: null, runVisible: false, run: null, sequence: 0 } },
 computed: { selectedShop() { return this.shops.find(s => s.channel_id === this.form.channel_id) } },
 created() { stockGet('/options').then(r => { this.shops = r.data.shops }).catch(() => { this.error = '店铺加载失败，请刷新重试' }); this.query.channelId = this.$route.query.channelId ? Number(this.$route.query.channelId) : undefined; this.query.skuSn = this.$route.query.skuSn || ''; this.load(); if (this.$route.query.id) this.open(this.$route.query.id); else if (this.$route.query.create) this.create() },
 beforeDestroy() { this.sequence++ },
 methods: {
  editable(link) { return !link.id || (link.last_submitted == null && link.pending_quantity == null && link.observed_quantity == null && link.state === 'NEW') },
  state(s) { return ({ NEW: '待配置 / 待同步', PENDING: '等待扫描执行', RUNNING: '处理中', SUCCESS: '成功', FAILED: '失败', UNKNOWN: '结果待核对', BLOCKED: '已暂停补高', CONFIRMED: '已人工核对' })[s] || s },
  tone(s) { return s === 'SUCCESS' ? 'success' : ['FAILED', 'UNKNOWN'].includes(s) ? 'danger' : s === 'BLOCKED' ? 'warning' : 'info' },
  busyState(s) { return ['RUNNING', 'PENDING'].includes(s) },
  search() { this.query.pageNum = 1; this.load() },
  async load() { this.loading = true; this.error = ''; try { const r = await stockGet('', this.query); this.rows = r.data.rows; this.total = r.data.total } catch (_) { this.error = '同步组加载失败，请刷新重试' } finally { this.loading = false } },
  create() { this.sequence++; this.form = { ...blank(), channel_id: this.query.channelId, sku_sn: this.query.skuSn }; this.bindingOptions = []; this.loadBindings(); this.projection = null; this.detailError = ''; this.visible = true; this.addLink() },
  close() { this.sequence++; this.projection = null },
  async open(id) { const seq = ++this.sequence; this.visible = true; this.detailLoading = true; this.detailError = ''; this.projection = null; try { const r = await stockGet('/' + id); if (seq === this.sequence) { this.form = r.data; if (this.form.quantity_cap === null) this.form.quantity_cap = undefined; this.form.links.forEach(l => { if (l.quantity_cap === null) l.quantity_cap = undefined }); this.loadBindings() } } catch (_) { if (seq === this.sequence) this.detailError = '详情加载失败，请关闭后重试' } finally { if (seq === this.sequence) this.detailLoading = false } },
  async loadBindings() { const seq=++this.bindingSequence; this.bindingOptions=[]; if(!this.form.channel_id || !this.form.sku_sn)return; const r=await productGet('/bound',{channelId:this.form.channel_id,skuSn:this.form.sku_sn}); if(seq===this.bindingSequence)this.bindingOptions=r.data },
  chooseBinding(link) { const b=this.bindingOptions.find(b=>b.binding_id===link.binding_id); if(!b)return; this.$set(link,'binding_revision',b.binding_revision); link.item_id=b.item_id; link.sku_id=b.sku_id; if(!link.name)link.name=b.title.slice(0,100) },
  addLink() { this.form.links.push({ name: '', binding_id: undefined, binding_revision: undefined, item_id: '', sku_id: '', weight: 100, quantity_cap: undefined, enabled: 1 }) },
  async save() { if (this.busy) return; if(this.form.links.some(l=>!l.retired_at && !l.binding_id))return this.$message.warning('请为每个链接选择有效的平台商品绑定'); this.busy = true; try { const r = await stockPost('', { ...this.form, quantity_cap: this.form.quantity_cap == null ? null : this.form.quantity_cap, links: this.form.links.map(l => ({ ...l, quantity_cap: l.quantity_cap == null ? null : l.quantity_cap })) }); this.form = r.data; this.projection = null; this.$message.success('已保存，自动同步按新配置执行'); this.load() } finally { this.busy = false } },
  async preview() { if (!this.form.id || this.busy) return; this.busy = true; this.projection = null; try { const r = await stockPost('/' + this.form.id + '/preview'); this.projection = r.data } finally { this.busy = false } },
  async enqueue(row) { if (this.busy) return; this.busy = true; try { const r = await stockPost('/' + row.id + '/run', { revision: row.revision }); if (this.form.id === row.id) this.form = r.data; this.$message.success('已提交，等待定时扫描执行，可刷新查看结果'); this.load() } finally { this.busy = false } },
  async linkAction(link, action) { const title = action === 'ZERO_DISABLE' ? '将平台库存设为0，并停止给此链接分配库存。' : '核对原请求及平台结果后，采用当前平台库存解除结果不明状态。'; let reason; try { const r = await this.$prompt(title + '请输入处理依据。', action === 'ZERO_DISABLE' ? '清零并退出' : '确认当前结果', { inputValidator: value => !!value && value.trim().length >= 2 && value.length <= 255 || '请填写2至255字处理依据' }); reason = r.value } catch (_) { return } this.busy = true; try { const r = await stockPost('/' + this.form.id + '/links/' + link.id + '/action', { revision: this.form.revision, action, confirmed: true, reason }); this.form = r.data; this.projection = null; this.load() } finally { this.busy = false } },
  async showRun(row) { const r = await stockGet('/' + this.form.id + '/runs/' + row.id); this.run = r.data; this.runVisible = true }
 }
}
</script>
<style scoped>
.heading,.section,.actions{display:flex;align-items:center;justify-content:space-between;gap:12px}.heading{margin-bottom:20px}.heading h2{margin:0 0 8px}.heading p,.muted{color:#7b8798;font-size:13px;line-height:1.6}.workspace{padding:0 24px 30px}.settings{display:grid;grid-template-columns:repeat(5,minmax(140px,1fr));gap:16px;margin-top:20px}.settings .el-select,.settings .el-input-number{width:100%}.section{margin-top:12px}.actions{justify-content:flex-start;flex-wrap:wrap;margin:20px 0}.warn{color:#a76812;font-size:13px;line-height:1.6}.summary{display:flex;gap:28px;padding:18px;background:#f4f7fb;margin:12px 0}.summary strong{display:block;font-size:22px;margin-top:8px;color:#24384c}.stock-sync h3{font-size:16px;margin-top:24px}@media(max-width:900px){.settings{grid-template-columns:repeat(2,minmax(120px,1fr))}.heading{align-items:flex-start}.workspace{padding:0 12px 20px}}
</style>
